mapper.insert:
INSERT
  INTO
       TB_MEMBER (
           MEMBER_NO
         , MEMBER_NAME
         , MEMBER_ID
         , MEMBER_PWD
         , PHONE
         , EMAIL
         , REF_RNO
         , MEMBER_IMAGE
         , MEMBER_POINT
         , ENROLL_DATE
         , STATUS
         , ROLE
       )
VALUES
       (
           SEQ_MNO.NEXTVAL
         , #{memberName}
         , #{memberId}
         , #{memberPwd}
         , #{phone}
         , #{email}
         , #{regionNo}
         , #{memberImageUrl}
         , #{memberPoint}
         , #{enrollDate}
         , #{status}
         , #{role}
       )
